import { KeepAwake } from "@capacitor-community/keep-awake";
import { Capacitor } from "@capacitor/core";

let wakeSentinel: { release: () => Promise<void> } | null = null;
let visibilityHandler: (() => void) | null = null;
let tapHandler: (() => void) | null = null;
let heartbeatTimer: ReturnType<typeof setInterval> | null = null;
let wantLock = false;
let fallbackVideo: HTMLVideoElement | null = null;
let videoActive = false;

// Tiny video blob from NoSleep.js (MIT, Rich Tibbett). Playing video keeps
// the screen on where Wake Lock API is unavailable (plain http has no secure
// context, so navigator.wakeLock is missing on phones).
const FALLBACK_WEBM =
    "data:video/webm;base64,";

function log(...args: unknown[]) {
    console.info("[keepawake]", ...args);
}

function hasWakeLock() {
    return typeof navigator !== "undefined" && "wakeLock" in navigator;
}

function getFallbackVideo() {
    if (fallbackVideo) return fallbackVideo;
    const video = document.createElement("video");
    video.setAttribute("playsinline", "");
    video.setAttribute("loop", "");
    video.muted = true;
    // 32px and nearly opaque: 1px/almost-transparent videos are treated as
    // hidden by the browser and don't hold the screen. Over the dark map it
    // still reads as a black pixel block in the corner.
    video.style.position = "fixed";
    video.style.left = "0";
    video.style.bottom = "0";
    video.style.width = "32px";
    video.style.height = "32px";
    video.style.opacity = "0.08";
    video.style.pointerEvents = "none";
    const source = document.createElement("source");
    source.src = FALLBACK_WEBM;
    source.type = "video/webm";
    video.appendChild(source);
    document.body.appendChild(video);
    fallbackVideo = video;
    return video;
}

async function requestVideoLock() {
    try {
        const video = getFallbackVideo();
        await video.play();
        videoActive = true;
        log("video lock active, paused =", video.paused);
    } catch (e) {
        videoActive = false;
        log("video play blocked:", (e as Error)?.name ?? e);
    }
}

function releaseVideoLock() {
    fallbackVideo?.pause();
    videoActive = false;
}

async function requestWakeLock() {
    try {
        const nav = navigator as Navigator & {
            wakeLock?: { request: (type: string) => Promise<{ release: () => Promise<void> }> };
        };
        if (!nav.wakeLock) return;
        if (document.visibilityState !== "visible") return;
        wakeSentinel = await nav.wakeLock.request("screen");
        log("wake lock active");
    } catch (e) {
        wakeSentinel = null;
        log("wake lock denied:", (e as Error)?.name ?? e);
    }
}

async function releaseWakeLock() {
    if (wakeSentinel) {
        try {
            await wakeSentinel.release();
        } catch {
            // Already released by the browser.
        }
        wakeSentinel = null;
    }
}

function ensureVisibilityHandler() {
    if (visibilityHandler) return;
    visibilityHandler = () => {
        if (wantLock && document.visibilityState === "visible") {
            void acquireLock();
        }
    };
    document.addEventListener("visibilitychange", visibilityHandler);
    // Autoplay policy may block video start without a gesture; any tap
    // retries the lock.
    tapHandler = () => {
        if (wantLock) {
            void acquireLock();
        }
    };
    document.addEventListener("pointerdown", tapHandler);
}

function clearVisibilityHandler() {
    if (visibilityHandler) {
        document.removeEventListener("visibilitychange", visibilityHandler);
        visibilityHandler = null;
    }
    if (tapHandler) {
        document.removeEventListener("pointerdown", tapHandler);
        tapHandler = null;
    }
}

async function acquireLock() {
    if (hasWakeLock()) {
        if (!wakeSentinel) await requestWakeLock();
        return;
    }
    if (!videoActive) await requestVideoLock();
    // Heartbeat: browsers may pause the video behind our back; nudge it.
    if (!heartbeatTimer) {
        heartbeatTimer = setInterval(() => {
            const video = fallbackVideo;
            if (wantLock && video && video.paused && document.visibilityState === "visible") {
                log("heartbeat: video paused, replaying");
                void video.play().catch(() => {});
            }
        }, 15000);
    }
}

async function applyNativeLock(enabled: boolean) {
    try {
        const result = await KeepAwake.isSupported();
        if (!result.isSupported) return;
        if (enabled) {
            await KeepAwake.keepAwake();
        } else {
            await KeepAwake.allowSleep();
        }
    } catch {
        // Plugin unavailable (e.g. plain web build).
    }
}

export const useKeepAwake = () => {
    const acquire = async () => {
        wantLock = true;
        log("acquire:", {
            protocol: location.protocol,
            secure: window.isSecureContext,
            native: Capacitor.isNativePlatform(),
            hasWakeLock: hasWakeLock(),
        });
        if (Capacitor.isNativePlatform()) {
            await applyNativeLock(true);
            return;
        }
        ensureVisibilityHandler();
        await acquireLock();
    };

    const release = async () => {
        wantLock = false;
        log("release");
        if (heartbeatTimer) {
            clearInterval(heartbeatTimer);
            heartbeatTimer = null;
        }
        if (Capacitor.isNativePlatform()) {
            await applyNativeLock(false);
            return;
        }
        clearVisibilityHandler();
        await releaseWakeLock();
        releaseVideoLock();
    };

    // Console probe: window.__keepAwake.state() / .acquire() / .release().
    function exposeProbe() {
        (window as unknown as Record<string, unknown>).__keepAwake = {
            state: () => ({
                wantLock,
                hasWakeLock: hasWakeLock(),
                secure: window.isSecureContext,
                protocol: location.protocol,
                sentinel: !!wakeSentinel,
                videoActive,
                videoPaused: fallbackVideo?.paused ?? null,
                videoTime: fallbackVideo?.currentTime ?? null,
            }),
            acquire,
            release,
        };
    }

    exposeProbe();

    const applySetting = async (enabled: boolean) => {
        if (enabled) {
            await acquire();
        } else {
            await release();
        }
    };

    return { acquire, release, applySetting };
};
